    7'd84: rom_row = 512'h00005387000000000000ac0000000000940000008f000000008100008e00000000000000000000000081000000000000008100a6000000000052000000690000;
    7'd85: rom_row = 512'h650000000000000000000000ba000000a40000000000b5000000005f00ab005d8100000000000000000000000000b10000000000008161a0007f000000000083;
    7'd86: rom_row = 512'h0000008100a50000a4000000000000000000000000000000007f0000000000000000a8000000000000a000000000000000000000000000000052000000000000;
    7'd87: rom_row = 512'h00aaa30000004d0000000000000000005600000000000000000000000000000000000000710000a9000000004d006b00000000008184004b0000000000000061;
    7'd88: rom_row = 512'h0000000000000000000000000000008c00007f000000000000730000000000520000a2000000000064000000008300000000000000006b00000000000000b600;
    7'd89: rom_row = 512'h00507a7f008100008200000000009b815b0000000000008e00000000000000000000a5007400000000ba00009f007f00000092007f000000000075a600810000;
    7'd90: rom_row = 512'h0000ac000000000000000000000000000000000000000000006c000000000000000000000000000000000000000000000048004c000000000000000000000000;
    7'd91: rom_row = 512'h0000000000000000007f0081000000007f00000000000000007f00005f007d00000000007f81000000810000ad000000006d814d000000570000007f00790044;
    7'd92: rom_row = 512'h00004e00000081000000007f00978181a6a5007a0081a381000000008100000081000000008e00000081ba00aa810000b0000000000000b90000009d00000081;
    7'd93: rom_row = 512'h940000810000009c747f00000000006b680000000000000000000000000000810081007f00acb27f0081ab7f81000000007f007f0000813e8181009f98810000;
    7'd94: rom_row = 512'h0000b9000000000050000000000000b800af00500000006000000000000000000000000054000000000000000000000000000000ac0000000000000000000000;
    7'd95: rom_row = 512'h0000000000000000000000000000000000000000000000000000b80000004c0000000000000000b19400ae004f00000000000000000098a7000000000000b000;
    7'd96: rom_row = 512'h815300f9b4e2b0c9e8b7c681ecd4c5ea99ec81f601a7b3cffcc981f6a0d6d381cc95ecc4ebbffb1329e38121e41298e1eae5c5ea392381a4e5d8a7d681e3fbb9;
    default: rom_row = 512'd0;
